\documentclass{article}
\usepackage{amsmath}
\begin{document}
\section{Derivation}
The log partition function of the model is
\begin{align}
Z = \sum_{\mathbf{s}} \exp\left( -\beta E(\mathbf{s}) \right) .
\end{align}
Taking derivatives yields the specific heat
\begin{align}
C = \beta^2 \left( \langle E^2 \rangle - \langle E \rangle^2 \right) .
\end{align}
\end{document}

